async (page) => {
  const ctx = page.context();
  await ctx.addCookies([{name:'cookieconsent_status',value:'dismiss',domain:'localhost',path:'/'},{name:'language',value:'en',domain:'localhost',path:'/'}]);
  await page.setViewportSize({width:1280,height:720});
  await page.goto('http://localhost:3000/#/search');
  await page.locator('mat-card').first().waitFor();
  const names = await page.locator('mat-card .item-name').allTextContents();
  const card = await page.locator('mat-card').filter({hasText:'Eggfruit'}).first().innerHTML();
  return {count: names.length, names, card: card.slice(0,3000)};
}

