async (page) => {
  const out = {};
  const field = page.getByRole('textbox',{name:'Coupon'});
  for (const code of ['abcdefghij','q:<Irhz3Tq','pEw8phz3Tq']) {
    await field.fill(code);
    await page.getByRole('button',{name:'Redeem'}).click();
    await page.waitForTimeout(1500);
    out[code] = await page.locator('app-payment mat-expansion-panel').nth(0).evaluate(e=>e.innerText);
    out[code+'_html'] = (await page.locator('app-payment').innerHTML()).match(/<(div|span|p)[^>]*(error|confirm|success)[^>]*>[^<]*/gi);
  }
  return out;
}

