async (page) => {
  await page.getByRole('button',{name:'Show/hide account menu'}).click();
  const menu1 = await page.locator('.mat-mdc-menu-panel').last().ariaSnapshot();
  await page.getByRole('menuitem',{name:/Orders & Payment/}).click();
  const menu2 = await page.locator('.mat-mdc-menu-panel').last().ariaSnapshot();
