async (page0) => {
  const B='http://localhost:3000';
  const ctxs = page0.context().browser().contexts();
  const page = ctxs[ctxs.length-1].pages()[0];
  const token = await page.evaluate(()=>localStorage.getItem('token'));
  const h = {Authorization:`Bearer ${token}`};
  const cards = await (await page.request.get(B+'/api/Cards',{headers:h})).json();
  const w = await page.request.put(B+'/rest/wallet/balance',{headers:h,data:{balance:3.99,paymentId:cards.data[0].id}});
  const wb = await w.text();
  await page.goto(B+'/#/basket');
  await page.locator('#checkoutButton').click();
  await page.getByRole('row').filter({hasText:'Test Customer'}).getByRole('radio').click();
  await page.getByRole('button',{name:'Proceed to payment selection'}).click();
  await page.getByRole('row',{name:/Standard Delivery/}).getByRole('radio').click();
  await page.getByRole('button',{name:'Proceed to delivery method selection'}).click();
  await page.getByText('My Payment Options').waitFor();
  await page.waitForTimeout(1000);
  const before = await page.getByText(/Wallet Balance/).locator('..').innerText();
  const pay = page.getByRole('button',{name:/^Pay /});
  const enabled = await pay.isEnabled();
  await pay.click();
  await page.waitForURL(/order-summary/);
  await page.locator('app-order-summary mat-row').first().waitFor();
  const summary = await page.locator('app-order-summary').innerText();
  await page.getByRole('button',{name:'Complete your purchase'}).click();
  await page.waitForURL(/order-completion/);
  await page.locator('app-order-completion mat-row').first().waitFor();
  await page.goto(B+'/#/wallet');
  await page.waitForTimeout(1500);
  const wallet = await page.locator('app-wallet').innerText();
  await page.goto(B+'/#/order-history');
  await page.waitForTimeout(1500);
  const hist = await page.locator('app-order-history').innerText();
  return {wb, before, enabled, summary, wallet, hist};
}

