import { encode } from 'z85';

const MONTHS = ['JAN', 'FEB', 'MAR', 'APR', 'MAY', 'JUN', 'JUL', 'AUG', 'SEP', 'OCT', 'NOV', 'DEC'];

/**
 * Coupon codes as test-cases/README.md defines them: Z85 of `<MMM><YY>-<NN>`.
 * The server accepts a coupon only in the month it names, in the local time of the machine.
 */
export class CouponHelper {
  static currentMonthCoupon(discountPercent: number, now = new Date()): string {
    return CouponHelper.couponFor(now, discountPercent);
  }

  static previousMonthCoupon(discountPercent: number, now = new Date()): string {
    const previousMonth = new Date(now.getFullYear(), now.getMonth() - 1, 1);
    return CouponHelper.couponFor(previousMonth, discountPercent);
  }

  private static couponFor(date: Date, discountPercent: number): string {
    const month = MONTHS[date.getMonth()];
    const year = String(date.getFullYear() % 100).padStart(2, '0');
    const discount = String(discountPercent).padStart(2, '0');
    return encode(`${month}${year}-${discount}`);
  }
}

