import type { BasketLine, DeliveryMethod, OrderTotals } from '@/utils/types/shop';

const CENTS_IN_UNIT = 100;
const PERCENT = 100;
const BONUS_POINT_DIVIDER = 10;
const CURRENCY_SIGN = '¤';

const toCents = (amount: number): number => Math.round(amount * CENTS_IN_UNIT);
const fromCents = (cents: number): number => cents / CENTS_IN_UNIT;

/** Expected prices of the shop, calculated in cents to avoid float drift. */
export class PriceHelper {
  /** `8.99` → `8.99¤`, the way the shop shows prices. */
  static format(amount: number): string {
    return `${amount.toFixed(2)}${CURRENCY_SIGN}`;
  }

  /** `5` → `5.00`, the way the shop shows a wallet balance. */
  static formatBalance(amount: number): string {
    return amount.toFixed(2);
  }

  static itemsTotal(lines: BasketLine[]): number {
    return fromCents(lines.reduce((sum, line) => sum + toCents(line.product.price) * line.quantity, 0));
  }

  static itemCount(lines: BasketLine[]): number {
    return lines.reduce((sum, line) => sum + line.quantity, 0);
  }

  static orderTotals(lines: BasketLine[], delivery: DeliveryMethod, discountPercent = 0): OrderTotals {
    const itemsCents = toCents(PriceHelper.itemsTotal(lines));
    const deliveryCents = toCents(delivery.price);
    const promotionCents = Math.round((itemsCents * discountPercent) / PERCENT);
    return {
      items: fromCents(itemsCents),
      delivery: fromCents(deliveryCents),
      promotion: fromCents(promotionCents),
      total: fromCents(itemsCents + deliveryCents - promotionCents),
    };
  }

  /** Bonus points of an order: product price / 10, rounded, × quantity. 1 point = 1.00¤. */
  static bonusPoints(lines: BasketLine[]): number {
    return lines.reduce((sum, line) => sum + Math.round(line.product.price / BONUS_POINT_DIVIDER) * line.quantity, 0);
  }

  static add(...amounts: number[]): number {
    return fromCents(amounts.reduce((sum, amount) => sum + toCents(amount), 0));
  }

  static subtract(from: number, amount: number): number {
    return fromCents(toCents(from) - toCents(amount));
  }
}

