import { expect, type Locator } from '@playwright/test';
import { DateHelper } from '@/utils/helpers/date-helper';

/** How long an absence or an unchanged value must hold before the check passes. */
export const HOLD_WINDOW_MS = DateHelper.secondsToMs(2);
const HOLD_POLL_INTERVAL_MS = 200;

export async function expectVisible(locator: Locator, description: string): Promise<void> {
  await expect(locator, `${description} is visible`).toBeVisible();
}

export async function expectHidden(locator: Locator, description: string): Promise<void> {
  await expect(locator, `${description} is hidden`).toBeHidden();
}

export async function expectText(locator: Locator, text: string | RegExp, description: string): Promise<void> {
  await expect(locator, `${description} has text ${String(text)}`).toHaveText(text);
}

export async function expectContainText(locator: Locator, text: string | RegExp, description: string): Promise<void> {
  await expect(locator, `${description} contains ${String(text)}`).toContainText(text);
}

export async function expectCount(locator: Locator, count: number, description: string): Promise<void> {
  await expect(locator, `${description}: count is ${count}`).toHaveCount(count);
}

export async function expectEnabled(locator: Locator, description: string): Promise<void> {
  await expect(locator, `${description} is enabled`).toBeEnabled();
}

export async function expectDisabled(locator: Locator, description: string): Promise<void> {
  await expect(locator, `${description} is disabled`).toBeDisabled();
}

export async function expectUrl(locator: Locator, url: RegExp, description: string): Promise<void> {
  await expect(locator.page(), `${description}: URL matches ${String(url)}`).toHaveURL(url);
}

/**
 * An absence needs a hold, not a retry (docs/core-beliefs.md, 3).
 * The locator must stay hidden for the whole hold window.
 */
export async function expectStaysHidden(locator: Locator, description: string): Promise<void> {
  await expectHolds(async () => {
    expect(await locator.count(), `${description} does not show`).toBe(0);
  });
}

/** The text must stay the same for the whole hold window. */
export async function expectKeepsText(locator: Locator, text: string, description: string): Promise<void> {
  await expectText(locator, text, description);
  await expectHolds(async () => {
    expect((await locator.innerText()).trim(), `${description} keeps text ${text}`).toBe(text);
  });
}

async function expectHolds(check: () => Promise<void>): Promise<void> {
  const deadline = Date.now() + HOLD_WINDOW_MS;
  while (Date.now() < deadline) {
    await check();
    await new Promise((resolve) => setTimeout(resolve, HOLD_POLL_INTERVAL_MS));
  }
  await check();
}

