import { BaseApiClient } from '@/core/api/base-api-client';
import { API_ROUTES } from '@/utils/constants/routes';
import type { Customer } from '@/utils/types/customer';
import type { SavedAddress, SavedCard } from '@/utils/types/shop';

interface CreatedCardResponse {
  data: { id: number };
}

/** Saved addresses, saved cards and the wallet of a customer. */
export class PaymentDataApiClient extends BaseApiClient {
  async saveAddress(customer: Customer, address: SavedAddress): Promise<void> {
    const response = await this.request.post(API_ROUTES.addresses, {
      headers: this.authHeaders(customer),
      data: address,
    });
    await this.expectOk(response, 'Save the address');
  }

  /** Returns the id of the saved card. */
  async saveCard(customer: Customer, card: SavedCard): Promise<number> {
    const response = await this.request.post(API_ROUTES.cards, {
      headers: this.authHeaders(customer),
      data: card,
    });
    await this.expectOk(response, 'Save the card');
    const { data } = (await response.json()) as CreatedCardResponse;
    return data.id;
  }

  /** Adds money to the wallet. The server takes it from a saved card of the customer. */
  async topUpWallet(customer: Customer, amount: number, cardId: number): Promise<void> {
    const response = await this.request.put(API_ROUTES.walletBalance, {
      headers: this.authHeaders(customer),
      data: { balance: amount, paymentId: cardId },
    });
    await this.expectOk(response, `Add ${amount} to the wallet`);
  }
}

