import type { Locator, Page } from '@playwright/test';
import {
  expectKeepsText,
  expectStaysHidden,
  expectText,
  expectVisible,
} from '@/utils/assertions/ui-assertions';

const MENU_ITEMS = {
  login: 'Login',
  logout: 'Logout',
  ordersAndPayment: 'Orders & Payment',
  orderHistory: 'Order History',
  digitalWallet: 'Digital Wallet',
} as const;

/** The top bar: the account menu and the basket button with its counter. */
export class NavbarComponent {
  private readonly accountButton: Locator;
  private readonly basketButton: Locator;
  private readonly basketCounter: Locator;
  private readonly menu: Locator;

  constructor(private readonly page: Page) {
    this.accountButton = page.getByRole('button', { name: 'Show/hide account menu' });
    this.basketButton = page.getByRole('button', { name: 'Show the shopping cart' });
    this.basketCounter = this.basketButton.locator('.fa-layers-counter, .warn-notification');
    this.menu = page.getByRole('menu');
  }

  private menuItem(text: string): Locator {
    return this.page.getByRole('menuitem').filter({ hasText: text });
  }

  async openAccountMenu(): Promise<void> {
    await this.accountButton.click();
    await expectVisible(this.menu.first(), 'Account menu');
  }

  async closeMenu(): Promise<void> {
    await this.page.keyboard.press('Escape');
    await expectStaysHidden(this.menu, 'Account menu');
  }

  async clickYourBasket(): Promise<void> {
    await this.basketButton.click();
  }

  async openOrderHistory(): Promise<void> {
    await this.openAccountMenu();
    await this.menuItem(MENU_ITEMS.ordersAndPayment).click();
    await this.menuItem(MENU_ITEMS.orderHistory).click();
  }

  async openDigitalWallet(): Promise<void> {
    await this.openAccountMenu();
    await this.menuItem(MENU_ITEMS.ordersAndPayment).click();
    await this.menuItem(MENU_ITEMS.digitalWallet).click();
  }

  async shouldSeeLoginMenuItem(): Promise<void> {
    await expectVisible(this.menuItem(MENU_ITEMS.login), 'Menu item `Login`');
  }

  async shouldSeeLogoutMenuItem(): Promise<void> {
    await expectVisible(this.menuItem(MENU_ITEMS.logout), 'Menu item `Logout`');
  }

  async shouldSeeEmailInMenu(email: string): Promise<void> {
    await expectVisible(this.menuItem(email), `Account email ${email} in the menu`);
  }

  async shouldNotSeeEmailInMenu(email: string): Promise<void> {
    await expectStaysHidden(this.menu.getByText(email), `Account email ${email} in the menu`);
  }

  async shouldSeeBasketCount(count: number): Promise<void> {
    await expectText(this.basketCounter, String(count), 'Basket counter');
  }

  /** The counter must not change later, for example after a rejected add. */
  async shouldKeepBasketCount(count: number): Promise<void> {
    await expectKeepsText(this.basketCounter, String(count), 'Basket counter');
  }
}

