  }

  async shouldSeePage(): Promise<void> {
    await expectUrl(this.page, new RegExp(`${UI_ROUTES.basket}$`), 'Basket page');
    await expectVisible(this.title, 'Basket title');
  }

  async shouldSeeRowCount(count: number): Promise<void> {
    await expectCount(this.rows, count, 'Basket rows');
  }

  async shouldSeeLine(line: BasketLine): Promise<void> {
    const { product, quantity } = line;
    await expectVisible(this.row(product), `Basket row of ${product.name}`);
    await expectText(this.quantity(product), String(quantity), `Quantity of ${product.name}`);
    await expectText(
      this.row(product).locator('.mat-column-price'),
      PriceHelper.format(product.price),
      `Price of ${product.name}`,
    );
  }

  /** After a rejected change: the quantity must not change later. */
  async shouldKeepQuantity(line: BasketLine): Promise<void> {
    await expectKeepsText(this.quantity(line.product), String(line.quantity), `Quantity of ${line.product.name}`);
  }

  async shouldNotSeeProduct(product: Product): Promise<void> {
    await expectStaysHidden(this.row(product), `Basket row of ${product.name}`);
  }

  async shouldSeeTotalPrice(amount: number): Promise<void> {
    await expectText(this.totalPrice, `${TOTAL_PRICE_LABEL} ${PriceHelper.format(amount)}`, 'Basket total price');
  }

  async shouldSeeEmptyBasket(): Promise<void> {
    await this.shouldSeeRowCount(0);
    await expectStaysHidden(this.rows, 'Basket rows');
  }

  async shouldSeeCheckoutDisabled(): Promise<void> {
    await expectDisabled(this.checkoutButton, 'Button `Checkout`');
  }
}

