import { WalletPaymentComponent } from '@/page-objects/components/wallet-payment.component';
import { UI_ROUTES } from '@/utils/constants/routes';
import { expectText, expectUrl, expectVisible } from '@/utils/assertions/ui-assertions';
import type { SavedCard } from '@/utils/types/shop';

const CARD_DIGITS_SHOWN = 4;
const CARD_MASK_CHAR = '*';

/** The checkout step `My Payment Options`: saved cards, the wallet and the coupon panel. */
export class PaymentPage extends BasePage {
  private readonly title: Locator;
  private readonly cardRows: Locator;
  private readonly continueButton: Locator;
  private readonly couponPanel: CouponPanelComponent;
  private readonly walletPayment: WalletPaymentComponent;

  constructor(page: Page) {
    super(page);
    const root = page.locator('app-payment');
    this.title = root.getByRole('heading', { name: 'My Payment Options' });
    this.cardRows = root.locator('app-payment-method mat-row');
    this.continueButton = root.getByRole('button', { name: 'Proceed to review' });
    this.couponPanel = new CouponPanelComponent(page);
    this.walletPayment = new WalletPaymentComponent(page);
  }

  static maskedCardNumber(card: SavedCard): string {
    const digits = String(card.cardNum);
    return digits.slice(-CARD_DIGITS_SHOWN).padStart(digits.length, CARD_MASK_CHAR);
  }

  private cardRow(card: SavedCard): Locator {
    return this.cardRows.filter({ hasText: PaymentPage.maskedCardNumber(card) });
  }

  async selectCard(card: SavedCard): Promise<void> {
    await this.cardRow(card).getByRole('radio').check();
  }

  async clickContinue(): Promise<void> {
    await this.continueButton.click();
  }

  async shouldSeePage(): Promise<void> {
    await expectUrl(this.page, new RegExp(`${UI_ROUTES.payment}$`), 'Payment step');
    await expectVisible(this.title, 'Title `My Payment Options`');
  }

  async shouldSeeSavedCard(card: SavedCard): Promise<void> {
    const cells = this.cardRow(card).getByRole('cell');
    await expectText(cells.nth(1), PaymentPage.maskedCardNumber(card), 'Card number');
    await expectText(cells.nth(2), card.fullName, 'Card holder');
    await expectText(cells.nth(3), `${card.expMonth}/${card.expYear}`, 'Card expiry');
  }

  async shouldSeeCouponPanel(): Promise<void> {
    await this.couponPanel.shouldSeePanel();
  }

  async openCouponPanel(): Promise<void> {
    await this.couponPanel.open();
  }

  async redeemCoupon(code: string): Promise<void> {
    await this.couponPanel.redeemCoupon(code);
  }

  async shouldSeeCouponDiscountMessage(discountPercent: number): Promise<void> {
    await this.couponPanel.shouldSeeDiscountMessage(discountPercent);
  }

  async shouldSeeCouponRejected(): Promise<void> {
    await this.couponPanel.shouldSeeRejectedMessage();
    await this.couponPanel.shouldNotSeeDiscountMessage();
  }

  async clickPayWithWallet(): Promise<void> {
    await this.walletPayment.clickPay();
  }

  async shouldSeeWalletBalance(amount: number): Promise<void> {
    await this.walletPayment.shouldSeeBalance(amount);
  }

  async shouldSeeWalletPayButton(amount: number): Promise<void> {
    await this.walletPayment.shouldSeePayButton(amount);
  }

  async shouldSeeWalletPayDisabled(): Promise<void> {
    await this.walletPayment.shouldSeePayButtonDisabled();
  }

  async shouldSeeWalletPayEnabled(): Promise<void> {
    await this.walletPayment.shouldSeePayButtonEnabled();
  }
}

