import type { Locator } from '@playwright/test';
import { expectCount, expectText, expectVisible } from '@/utils/assertions/ui-assertions';
import { PriceHelper } from '@/utils/helpers/price-helper';
import type { BasketLine } from '@/utils/types/shop';

/** A table of ordered products: product, price, quantity, line total. */
export class OrderLinesComponent {
  private readonly rows: Locator;

  constructor(root: Locator) {
    this.rows = root.locator('mat-row');
  }

  private row(line: BasketLine): Locator {
    return this.rows.filter({ has: this.rows.page().locator('.mat-column-product', { hasText: line.product.name }) });
  }

  async shouldSeeLines(lines: BasketLine[]): Promise<void> {
    await expectCount(this.rows, lines.length, 'Order lines');
    for (const line of lines) {
      await this.shouldSeeLine(line);
    }
  }

  async shouldSeeLine(line: BasketLine): Promise<void> {
    const { product, quantity } = line;
    const row = this.row(line);
    await expectVisible(row, `Order line of ${product.name}`);
    await expectText(row.locator('.mat-column-price'), PriceHelper.format(product.price), `Price of ${product.name}`);
    await expectText(row.locator('.mat-column-quantity'), String(quantity), `Quantity of ${product.name}`);
  }
}

