import type { Locator, Page } from '@playwright/test';
import { BasePage } from '@/page-objects/base-page';
import { OrderLinesComponent } from '@/page-objects/components/order-lines.component';
import { UI_ROUTES } from '@/utils/constants/routes';
import { UI_MESSAGES } from '@/utils/constants/ui-messages';
import { expectText, expectUrl } from '@/utils/assertions/ui-assertions';
import { PriceHelper } from '@/utils/helpers/price-helper';
import type { BasketLine, OrderTotals } from '@/utils/types/shop';

const ORDER_ID_PATTERN = '[0-9a-f]+-[0-9a-f]+';

/** The confirmation page `/#/order-completion/<order ID>`. It shows the total that the server saved. */
export class OrderCompletionPage extends BasePage {
  private readonly title: Locator;
  private readonly orderLines: OrderLinesComponent;
  private readonly totalsValues: Locator;

  constructor(page: Page) {
    super(page);
    const root = page.locator('app-order-completion');
    this.title = root.getByRole('heading', { level: 1 });
    this.orderLines = new OrderLinesComponent(root, true);
    // Footer cells: Items, Delivery, Promotion, Total Price, in this order.
    this.totalsValues = root.locator('mat-footer-row .mat-column-total-price tr');
  }

  async shouldSeeOrderPlaced(): Promise<void> {
    await expectUrl(this.page, new RegExp(`${UI_ROUTES.orderCompletion}${ORDER_ID_PATTERN}$`), 'Order confirmation page');
    await expectText(this.title, UI_MESSAGES.orderPlaced, 'Order confirmation message');
  }

  /** The order ID from the URL `/#/order-completion/<order ID>`. */
  orderId(): string {
    const match = this.page.url().match(new RegExp(`order-completion/(${ORDER_ID_PATTERN})$`));
    if (!match) {
      throw new Error(`No order ID in the URL ${this.page.url()}`);
    }
    return match[1];
  }

  async shouldSeeLines(lines: BasketLine[]): Promise<void> {
    await this.orderLines.shouldSeeLines(lines);
  }

  async shouldSeeTotals(totals: OrderTotals): Promise<void> {
    const values = [totals.items, totals.delivery, totals.promotion, totals.total];
    const labels = ['Items', 'Delivery', 'Promotion', 'Total Price'];
    for (const [index, value] of values.entries()) {
      await expectText(this.totalsValues.nth(index), PriceHelper.format(value), labels[index]);
    }
  }
}

