/**
 * Test-data setup through the API: a new customer, the basket, the saved address and card, the wallet.
 * Every test that needs an account calls createCustomer inside test() (test-user-lifecycle.md).
 */
import { randomUUID } from 'node:crypto';
import type { ApiClients } from '@/core/api/api-clients';
import { CUSTOMER_EMAIL_DOMAIN, SAVED_ADDRESS, SAVED_CARD } from '@/utils/constants/test-data';
import type { Customer } from '@/utils/types/customer';
import type { BasketLine } from '@/utils/types/shop';

const WRONG_PASSWORD_SUFFIX = 'x';

/** A customer with a saved address and a saved card. */
export interface CheckoutCustomer {
  customer: Customer;
  cardId: number;
}

/** Registers a new normal customer with a unique email and returns its API session. */
export async function createCustomer(api: ApiClients): Promise<Customer> {
  const unique = `${Date.now()}-${randomUUID().slice(0, 8)}`;
  const email = `customer-${unique}@${CUSTOMER_EMAIL_DOMAIN}`;
  const password = `Passw0rd!${unique}`;
  await api.users.register(email, password);
  return api.users.login(email, password);
}

/** The account password with one more character (TC test data `Wrong password`). */
export function wrongPasswordFor(customer: Customer): string {
  return `${customer.password}${WRONG_PASSWORD_SUFFIX}`;
}

export async function fillBasket(api: ApiClients, customer: Customer, lines: BasketLine[]): Promise<void> {
  for (const line of lines) {
    await api.basket.addLine(customer, line);
  }
}

/** A new customer with the saved address and the saved card of test-cases/README.md. */
export async function createCheckoutCustomer(api: ApiClients): Promise<CheckoutCustomer> {
  const customer = await createCustomer(api);
  await api.paymentData.saveAddress(customer, SAVED_ADDRESS);
  const cardId = await api.paymentData.saveCard(customer, SAVED_CARD);
  return { customer, cardId };
}

/** Adds money to the wallet with the saved card. */
export async function topUpWallet(api: ApiClients, checkoutCustomer: CheckoutCustomer, amount: number): Promise<void> {
  await api.paymentData.topUpWallet(checkoutCustomer.customer, amount, checkoutCustomer.cardId);
}

