/**
 * UI flows through the checkout steps that several specs repeat:
 * basket → `Select an address` → `Choose a delivery speed` → `My Payment Options`.
 */
import type { AddressSelectPage } from '@/page-objects/address-select-page';
import type { BasketPage } from '@/page-objects/basket-page';
import type { DeliveryMethodPage } from '@/page-objects/delivery-method-page';
import type { PaymentPage } from '@/page-objects/payment-page';
import type { DeliveryMethod, SavedAddress } from '@/utils/types/shop';

interface CheckoutPages {
  basketPage: BasketPage;
  addressSelectPage: AddressSelectPage;
  deliveryMethodPage: DeliveryMethodPage;
  paymentPage: PaymentPage;
}

/** Opens the basket, clicks `Checkout`, selects the address and continues to the delivery step. */
export async function checkoutToDeliveryStep(pages: CheckoutPages, address: SavedAddress): Promise<void> {
  await pages.basketPage.open();
  await pages.basketPage.clickCheckout();
