import { test } from '@/fixtures/pages.fixture';
import { createCustomer } from '@/tests/helpers/customer-flows';
import { AUTOTEST_PLAYWRIGHT_TAGS } from '@/utils/constants/autotest-labels';
import { PRODUCTS } from '@/utils/constants/products';
import { UI_MESSAGES } from '@/utils/constants/ui-messages';
import { PriceHelper } from '@/utils/helpers/price-helper';

test('Add a product to an empty basket from the product list', {
  tag: [AUTOTEST_PLAYWRIGHT_TAGS.cart],
  annotation: { type: 'test-case', description: 'TC-02' },
}, async ({ api, loginPage, searchPage, basketPage }) => {
  const product = PRODUCTS.eggfruitJuice;
  const basketLines = [{ product, quantity: 1 }];

  await test.step('Precondition: log in a new customer with an empty basket', async () => {
    const customer = await createCustomer(api);
    await loginPage.authenticate(customer);
  });

  await test.step('1. Open the product list', async () => {
    await searchPage.open();
    await searchPage.shouldSeeProduct(product);
    await searchPage.navbar.shouldSeeBasketCount(0);
  });

  await test.step('2. Click `Add to Basket` on the product', async () => {
    await searchPage.clickAddToBasket(product);
    await searchPage.snackBar.shouldSeeMessage(UI_MESSAGES.productPlacedInBasket(product.name));
    await searchPage.navbar.shouldSeeBasketCount(PriceHelper.itemCount(basketLines));
  });

  await test.step('3. Open the basket with the button `Your Basket`', async () => {
    await searchPage.navbar.clickYourBasket();
    await basketPage.shouldSeePage();
    await basketPage.shouldSeeRowCount(basketLines.length);
    await basketPage.shouldSeeLine(basketLines[0]);
  });

  await test.step('4. Read the total of the basket', async () => {
    await basketPage.shouldSeeTotalPrice(PriceHelper.itemsTotal(basketLines));
  });
});

