import { test } from '@/fixtures/pages.fixture';
import { createCustomer } from '@/tests/helpers/customer-flows';
import { AUTOTEST_PLAYWRIGHT_TAGS } from '@/utils/constants/autotest-labels';
import { PRODUCTS, PURCHASE_LIMIT } from '@/utils/constants/products';
import { UI_MESSAGES } from '@/utils/constants/ui-messages';
import { PriceHelper } from '@/utils/helpers/price-helper';

test('A normal customer cannot add more items of a product than its purchase limit', {
  tag: [AUTOTEST_PLAYWRIGHT_TAGS.cart],
  annotation: { type: 'test-case', description: 'TC-04' },
}, async ({ api, loginPage, searchPage, basketPage }) => {
  const product = PRODUCTS.appleJuice;
  const limit = PURCHASE_LIMIT.appleJuice;
  const lineAtLimit = { product, quantity: limit };
  const limitMessage = UI_MESSAGES.purchaseLimitReached(limit);

  await test.step('Precondition: log in a new normal customer with an empty basket', async () => {
    const customer = await createCustomer(api);
    await loginPage.authenticate(customer);
  });

  await test.step('1. Open the product list and click `Add to Basket` on the product', async () => {
    await searchPage.open();
    await searchPage.clickAddToBasket(product);
    await searchPage.snackBar.shouldSeeMessage(UI_MESSAGES.productPlacedInBasket(product.name));
    await searchPage.navbar.shouldSeeBasketCount(1);
  });

  await test.step(`2. Open the basket and click plus until the quantity is ${limit}`, async () => {
    await basketPage.open();
    for (let quantity = 2; quantity <= limit; quantity++) {
      await basketPage.clickIncreaseQuantity(product);
      await basketPage.shouldSeeLine({ product, quantity });
    }
    await basketPage.shouldSeeTotalPrice(PriceHelper.itemsTotal([lineAtLimit]));
    await basketPage.snackBar.shouldNotSeeMessage(limitMessage);
  });

  await test.step('3. Click the plus button one more time', async () => {
    await basketPage.clickIncreaseQuantity(product);
    await basketPage.snackBar.shouldSeeMessage(limitMessage);
  });

  await test.step('4. Read the basket', async () => {
    await basketPage.shouldKeepQuantity(lineAtLimit);
    await basketPage.shouldSeeTotalPrice(PriceHelper.itemsTotal([lineAtLimit]));
    await basketPage.navbar.shouldSeeBasketCount(limit);
  });

  await test.step('5. Open the product list and click `Add to Basket` on the product', async () => {
    await searchPage.open();
    await searchPage.clickAddToBasket(product);
    await searchPage.snackBar.shouldSeeMessage(limitMessage);
    await searchPage.navbar.shouldKeepBasketCount(limit);
  });
});

