import type { Locator, Page } from '@playwright/test';
import { expectContainText } from '@/utils/assertions/ui-assertions';

/** The short message at the bottom of the page (`Placed ... into basket.`, limit errors). */
export class SnackBarComponent {
  private readonly message: Locator;

  constructor(page: Page) {
    this.message = page.locator('simple-snack-bar');
  }

  async shouldSeeMessage(text: string): Promise<void> {
    await expectContainText(this.message.filter({ hasText: text }).last(), text, 'Snack bar message');
