import { test } from '@/fixtures/pages.fixture';
import { checkoutToDeliveryStep, chooseDeliveryAndContinue } from '@/tests/helpers/checkout-flows';
import { createCheckoutCustomer, fillBasket } from '@/tests/helpers/customer-flows';
import { AUTOTEST_PLAYWRIGHT_TAGS } from '@/utils/constants/autotest-labels';
import { DELIVERY_METHODS } from '@/utils/constants/delivery-methods';
import { PRODUCTS } from '@/utils/constants/products';
import { COUPON_DISCOUNT_PERCENT, SAVED_ADDRESS, SAVED_CARD } from '@/utils/constants/test-data';
import { CouponHelper } from '@/utils/helpers/coupon-helper';
import { PriceHelper } from '@/utils/helpers/price-helper';

test('A coupon of the current month lowers the price of the products on the payment step', {
  tag: [AUTOTEST_PLAYWRIGHT_TAGS.coupon],
  annotation: { type: 'test-case', description: 'TC-05' },
}, async ({ api, loginPage, basketPage, addressSelectPage, deliveryMethodPage, paymentPage, orderSummaryPage }) => {
  const basketLines = [{ product: PRODUCTS.eggfruitJuice, quantity: 2 }];
  const delivery = DELIVERY_METHODS.oneDay;
  const checkoutPages = { basketPage, addressSelectPage, deliveryMethodPage, paymentPage };

  await test.step('Precondition: log in a new customer with a saved address, a saved card and the product in the basket', async () => {
    const { customer } = await createCheckoutCustomer(api);
    await fillBasket(api, customer, basketLines);
    await loginPage.authenticate(customer);
  });

  await test.step('1. Open the basket and click `Checkout`', async () => {
    await basketPage.open();
    await basketPage.clickCheckout();
    await addressSelectPage.shouldSeePage();
    await addressSelectPage.shouldSeeSavedAddress(SAVED_ADDRESS);
  });

  await test.step('2. Select the saved address and continue', async () => {
    await addressSelectPage.selectAddress(SAVED_ADDRESS);
    await addressSelectPage.clickContinue();
    await deliveryMethodPage.shouldSeePage();
    await deliveryMethodPage.shouldSeeDeliveryMethod(DELIVERY_METHODS.oneDay);
    await deliveryMethodPage.shouldSeeDeliveryMethod(DELIVERY_METHODS.fast);
    await deliveryMethodPage.shouldSeeDeliveryMethod(DELIVERY_METHODS.standard);
  });

  await test.step(`3. Select \`${delivery.name}\` and continue`, async () => {
    await chooseDeliveryAndContinue(checkoutPages, delivery);
    await paymentPage.shouldSeePage();
    await paymentPage.shouldSeeSavedCard(SAVED_CARD);
    await paymentPage.shouldSeeCouponPanel();
  });

  await test.step('4. Redeem the coupon of the current month', async () => {
    await paymentPage.openCouponPanel();
    await paymentPage.redeemCoupon(CouponHelper.currentMonthCoupon(COUPON_DISCOUNT_PERCENT));
    await paymentPage.shouldSeeCouponDiscountMessage(COUPON_DISCOUNT_PERCENT);
  });

  await test.step('5. Select the saved card and continue', async () => {
    await paymentPage.selectCard(SAVED_CARD);
    await paymentPage.clickContinue();
    await orderSummaryPage.shouldSeePage();
    await orderSummaryPage.shouldSeeTotals(PriceHelper.orderTotals(basketLines, delivery, COUPON_DISCOUNT_PERCENT));
  });

  void checkoutToDeliveryStep;
});

