import type { Locator, Page } from '@playwright/test';
import { BasePage } from '@/page-objects/base-page';
import { OrderLinesComponent } from '@/page-objects/components/order-lines.component';
import { UI_ROUTES } from '@/utils/constants/routes';
import { UI_MESSAGES } from '@/utils/constants/ui-messages';
import { expectCount, expectText, expectUrl, expectVisible } from '@/utils/assertions/ui-assertions';
import { PriceHelper } from '@/utils/helpers/price-helper';
import type { BasketLine } from '@/utils/types/shop';

/** What the order history shows in the heading of one order. */
export interface OrderHistoryEntry {
  orderId?: string;
  total: number;
  bonus?: number;
  lines: BasketLine[];
}

/** The page `Order History`. */
export class OrderHistoryPage extends BasePage {
  private readonly title: Locator;
  private readonly orders: Locator;
  private readonly emptyMessage: Locator;

  constructor(page: Page) {
    super(page);
    const root = page.locator('app-order-history');
    this.title = root.locator('mat-card-title');
    this.orders = root.locator('.table-container');
    this.emptyMessage = root.getByText(UI_MESSAGES.orderHistoryEmpty);
  }

  /** The value under a heading label (`Order ID`, `Total Price`, `Bonus`) of one order. */
  private headingValue(order: Locator, label: string): Locator {
    return order.locator('.col-vertical').filter({ has: order.page().getByText(label, { exact: true }) }).locator('div').last();
  }

  async shouldSeePage(): Promise<void> {
    await expectUrl(this.page, new RegExp(`${UI_ROUTES.orderHistory}$`), 'Order history');
    await expectText(this.title, 'Order History', 'Title `Order History`');
  }

  async shouldSeeNoOrders(): Promise<void> {
    await expectVisible(this.emptyMessage, 'Message about an empty order history');
    await expectCount(this.orders, 0, 'Orders');
  }

  async shouldSeeOrderCount(count: number): Promise<void> {
    await expectCount(this.orders, count, 'Orders');
  }

  async shouldSeeOrder(entry: OrderHistoryEntry): Promise<void> {
    const order = entry.orderId ? this.orders.filter({ hasText: `#${entry.orderId}` }) : this.orders.first();
    if (entry.orderId) {
      await expectText(this.headingValue(order, 'Order ID'), `#${entry.orderId}`, 'Order ID');
    }
    await expectText(this.headingValue(order, 'Total Price'), PriceHelper.format(entry.total), 'Order total price');
    if (entry.bonus !== undefined) {
      await expectText(this.headingValue(order, 'Bonus'), String(entry.bonus), 'Order bonus');
    }
    await new OrderLinesComponent(order, true).shouldSeeLines(entry.lines);
  }
}

