import type { Locator, Page } from '@playwright/test';
import { BasePage } from '@/page-objects/base-page';
import { OrderLinesComponent } from '@/page-objects/components/order-lines.component';
import { PaymentPage } from '@/page-objects/payment-page';
import { UI_ROUTES } from '@/utils/constants/routes';
import { expectContainText, expectText, expectUrl, expectVisible } from '@/utils/assertions/ui-assertions';
import { PriceHelper } from '@/utils/helpers/price-helper';
import type { BasketLine, OrderTotals, SavedAddress, SavedCard } from '@/utils/types/shop';

const TOTALS_LABELS = {
  items: 'Items',
  delivery: 'Delivery',
  promotion: 'Promotion',
  total: 'Total Price',
} as const;

/** The checkout step `Order Summary`, before the order is placed. */
export class OrderSummaryPage extends BasePage {
  private readonly root: Locator;
  private readonly totalsTable: Locator;
  private readonly placeOrderButton: Locator;
  private readonly orderLines: OrderLinesComponent;

  constructor(page: Page) {
    super(page);
    this.root = page.locator('app-order-summary');
    this.totalsTable = this.root.locator('.order-summary + table');
    this.placeOrderButton = this.root.getByRole('button', { name: 'Complete your purchase' });
    this.orderLines = new OrderLinesComponent(this.root.locator('app-purchase-basket'), false);
  }

  private totalsValue(label: string): Locator {
    return this.totalsTable.locator('tr').filter({ hasText: label }).locator('td').last();
  }

  async clickPlaceOrderAndPay(): Promise<void> {
    await this.placeOrderButton.click();
  }

  async shouldSeePage(): Promise<void> {
    await expectUrl(this.page, new RegExp(`${UI_ROUTES.orderSummary}$`), 'Order summary');
    await expectText(this.placeOrderButton, 'Place your order and pay', 'Button `Place your order and pay`');
  }

  async shouldSeeLines(lines: BasketLine[]): Promise<void> {
    await this.orderLines.shouldSeeLines(lines);
  }

  async shouldSeeTotals(totals: OrderTotals): Promise<void> {
    await expectVisible(this.totalsTable, 'Order summary totals');
    await expectText(this.totalsValue(TOTALS_LABELS.items), PriceHelper.format(totals.items), 'Items');
    await expectText(this.totalsValue(TOTALS_LABELS.delivery), PriceHelper.format(totals.delivery), 'Delivery');
    await expectText(this.totalsValue(TOTALS_LABELS.promotion), PriceHelper.format(totals.promotion), 'Promotion');
    await expectText(this.totalsValue(TOTALS_LABELS.total), PriceHelper.format(totals.total), 'Total Price');
  }

  private exactText(text: string): Locator {
    return this.root.getByText(text, { exact: true });
  }

  async shouldSeeDeliveryAddress(address: SavedAddress): Promise<void> {
    await expectVisible(this.exactText('Delivery Address'), 'Block `Delivery Address`');
    await expectVisible(this.exactText(address.fullName).first(), 'Address name');
    await expectVisible(
      this.exactText(`${address.streetAddress}, ${address.city}, ${address.state}, ${address.zipCode}`),
      'Address line',
    );
    await expectVisible(this.exactText(address.country), 'Address country');
  }

  async shouldSeeCardPayment(card: SavedCard): Promise<void> {
    const lastDigits = PaymentPage.maskedCardNumber(card).replace(/\*/g, '');
    await this.shouldSeePaymentMethod(`Card ending in ${lastDigits}`);
    await expectContainText(this.root, card.fullName, 'Card holder');
  }

  async shouldSeePaymentMethod(paymentMethod: string): Promise<void> {
    await expectVisible(this.exactText('Payment Method'), 'Block `Payment Method`');
    await expectVisible(this.exactText(paymentMethod), `Payment method ${paymentMethod}`);
  }
}

