test('Order with a card and a coupon, from the basket to the order history', {
  tag: [AUTOTEST_PLAYWRIGHT_TAGS.checkout],
  annotation: { type: 'test-case', description: 'TC-07' },
}, async ({
  api,
  loginPage,
  searchPage,
  basketPage,
  addressSelectPage,
  deliveryMethodPage,
  paymentPage,
  orderSummaryPage,
  orderCompletionPage,
  orderHistoryPage,
}) => {
  // Ten steps through the whole checkout, with hold checks for absences.
  test.setTimeout(DateHelper.minutesToMs(2));

  const lineA = { product: PRODUCTS.eggfruitJuice, quantity: 2 };
  const lineB = { product: PRODUCTS.carrotJuice, quantity: 1 };
  const basketLines = [lineA, lineB];
  const delivery = DELIVERY_METHODS.oneDay;
  const orderTotals = PriceHelper.orderTotals(basketLines, delivery, COUPON_DISCOUNT_PERCENT);
  const checkoutPages = { basketPage, addressSelectPage, deliveryMethodPage, paymentPage };
  let orderId = '';

  await test.step('Precondition: log in a new customer with a saved address, a saved card and an empty basket', async () => {
    const { customer } = await createCheckoutCustomer(api);
    await loginPage.authenticate(customer);
  });

  await test.step('1. Add product A two times and product B one time from the product list', async () => {
    await searchPage.open();
    for (let added = 0; added < lineA.quantity; added++) {
      await searchPage.clickAddToBasket(lineA.product);
    }
    await searchPage.clickAddToBasket(lineB.product);
    await searchPage.navbar.shouldSeeBasketCount(PriceHelper.itemCount(basketLines));
  });

  await test.step('2. Open the basket', async () => {
    await basketPage.open();
    await basketPage.shouldSeeLine(lineA);
    await basketPage.shouldSeeLine(lineB);
    await basketPage.shouldSeeTotalPrice(PriceHelper.itemsTotal(basketLines));
  });

  await test.step('3. Click `Checkout`, select the saved address and continue', async () => {
    await checkoutToDeliveryStep(checkoutPages, SAVED_ADDRESS);
    await deliveryMethodPage.shouldSeePage();
  });

  await test.step(`4. Select \`${delivery.name}\` and continue`, async () => {
    await chooseDeliveryAndContinue(checkoutPages, delivery);
    await paymentPage.shouldSeePage();
  });

  await test.step('5. Redeem the coupon of the current month', async () => {
    await paymentPage.openCouponPanel();
    await paymentPage.redeemCoupon(CouponHelper.currentMonthCoupon(COUPON_DISCOUNT_PERCENT));
    await paymentPage.shouldSeeCouponDiscountMessage(COUPON_DISCOUNT_PERCENT);
  });

  await test.step('6. Select the saved card and continue', async () => {
    await paymentPage.selectCard(SAVED_CARD);
    await paymentPage.clickContinue();
    await orderSummaryPage.shouldSeePage();
    await orderSummaryPage.shouldSeeDeliveryAddress(SAVED_ADDRESS);
    await orderSummaryPage.shouldSeeCardPayment(SAVED_CARD);
    await orderSummaryPage.shouldSeeLines(basketLines);
    await orderSummaryPage.shouldSeeTotals(orderTotals);
  });

  await test.step('7. Click `Place your order and pay`', async () => {
    await orderSummaryPage.clickPlaceOrderAndPay();
    await orderCompletionPage.shouldSeeOrderPlaced();
    orderId = orderCompletionPage.orderId();
  });

  await test.step('8. Read the order summary on the confirmation page', async () => {
    await orderCompletionPage.shouldSeeLines(basketLines);
    await orderCompletionPage.shouldSeeTotals(orderTotals);
  });

  await test.step('9. Read the basket counter and open the basket', async () => {
    await orderCompletionPage.navbar.shouldSeeBasketCount(0);
    await basketPage.open();
    await basketPage.shouldSeeEmptyBasket();
    await basketPage.shouldSeeCheckoutDisabled();
  });

  await test.step('10. Open `Order History` from the account menu', async () => {
    await basketPage.navbar.openOrderHistory();
    await orderHistoryPage.shouldSeePage();
    await orderHistoryPage.shouldSeeOrderCount(1);
    await orderHistoryPage.shouldSeeOrder({ orderId, total: orderTotals.total, lines: basketLines });
  });
});

import { test } from '@/fixtures/pages.fixture';
import { checkoutToDeliveryStep, chooseDeliveryAndContinue } from '@/tests/helpers/checkout-flows';
import {
  createCheckoutCustomer,
  fillBasket,
  topUpWallet,
  type CheckoutCustomer,
} from '@/tests/helpers/customer-flows';
import { AUTOTEST_PLAYWRIGHT_TAGS } from '@/utils/constants/autotest-labels';
import { DELIVERY_METHODS } from '@/utils/constants/delivery-methods';
import { PRODUCTS } from '@/utils/constants/products';
import { SAVED_ADDRESS, WALLET_AMOUNTS } from '@/utils/constants/test-data';
import { UI_MESSAGES } from '@/utils/constants/ui-messages';
import { DateHelper } from '@/utils/helpers/date-helper';
import { PriceHelper } from '@/utils/helpers/price-helper';

test('Pay an order with the wallet only when the balance covers the order total', {
  tag: [AUTOTEST_PLAYWRIGHT_TAGS.wallet],
  annotation: { type: 'test-case', description: 'TC-08' },
}, async ({
  api,
  loginPage,
  basketPage,
  addressSelectPage,
  deliveryMethodPage,
  paymentPage,
  orderSummaryPage,
  orderCompletionPage,
  orderHistoryPage,
  walletPage,
}) => {
  // Two passes through the checkout, with hold checks for absences.
  test.setTimeout(DateHelper.minutesToMs(2));

  const basketLines = [{ product: PRODUCTS.eggfruitJuice, quantity: 1 }];
  const delivery = DELIVERY_METHODS.standard;
  const orderTotal = PriceHelper.orderTotals(basketLines, delivery).total;
  const fullBalance = PriceHelper.add(WALLET_AMOUNTS.firstBalance, WALLET_AMOUNTS.topUpToOrderTotal);
  const bonus = PriceHelper.bonusPoints(basketLines);
  const checkoutPages = { basketPage, addressSelectPage, deliveryMethodPage, paymentPage };
  let checkoutCustomer: CheckoutCustomer;

  await test.step('Precondition: log in a new customer with a saved address, a saved card, the product in the basket and 5.00 in the wallet', async () => {
    checkoutCustomer = await createCheckoutCustomer(api);
    await fillBasket(api, checkoutCustomer.customer, basketLines);
    await topUpWallet(api, checkoutCustomer, WALLET_AMOUNTS.firstBalance);
    await loginPage.authenticate(checkoutCustomer.customer);
  });

  await test.step('1. Open the basket, check out, select the saved address and continue', async () => {
    await checkoutToDeliveryStep(checkoutPages, SAVED_ADDRESS);
    await deliveryMethodPage.shouldSeePage();
  });

  await test.step(`2. Select \`${delivery.name}\` and continue`, async () => {
    await chooseDeliveryAndContinue(checkoutPages, delivery);
    await paymentPage.shouldSeePage();
    await paymentPage.shouldSeeWalletBalance(WALLET_AMOUNTS.firstBalance);
    await paymentPage.shouldSeeWalletPayButton(orderTotal);
  });

  await test.step('3. Read the button `Pay`', async () => {
    await paymentPage.shouldSeeWalletPayDisabled();
  });

  await test.step('4. Open `Order History` from the account menu', async () => {
    await paymentPage.navbar.openOrderHistory();
    await orderHistoryPage.shouldSeePage();
    await orderHistoryPage.shouldSeeNoOrders();
  });

  await test.step('5. Open `Digital Wallet` from the account menu', async () => {
    await orderHistoryPage.navbar.openDigitalWallet();
    await walletPage.shouldSeePage();
    await walletPage.shouldSeeBalance(WALLET_AMOUNTS.firstBalance);
  });

  await test.step('Precondition: add 3.99 to the wallet with the saved card', async () => {
    await topUpWallet(api, checkoutCustomer, WALLET_AMOUNTS.topUpToOrderTotal);
  });

  await test.step(`6. Check out again with the saved address and \`${delivery.name}\``, async () => {
    await checkoutToDeliveryStep(checkoutPages, SAVED_ADDRESS);
    await chooseDeliveryAndContinue(checkoutPages, delivery);
    await paymentPage.shouldSeePage();
    await paymentPage.shouldSeeWalletBalance(fullBalance);
    await paymentPage.shouldSeeWalletPayButton(orderTotal);
    await paymentPage.shouldSeeWalletPayEnabled();
  });

  await test.step('7. Click `Pay`', async () => {
    await paymentPage.clickPayWithWallet();
    await orderSummaryPage.shouldSeePage();
    await orderSummaryPage.shouldSeePaymentMethod(UI_MESSAGES.digitalWalletPayment);
    await orderSummaryPage.shouldSeeTotals(PriceHelper.orderTotals(basketLines, delivery));
  });

  await test.step('8. Click `Place your order and pay`', async () => {
    await orderSummaryPage.clickPlaceOrderAndPay();
    await orderCompletionPage.shouldSeeOrderPlaced();
  });

  await test.step('9. Open `Digital Wallet` from the account menu', async () => {
    await orderCompletionPage.navbar.openDigitalWallet();
    await walletPage.shouldSeePage();
    await walletPage.shouldSeeBalance(PriceHelper.add(PriceHelper.subtract(fullBalance, orderTotal), bonus));
  });

  await test.step('10. Open `Order History` from the account menu', async () => {
    await walletPage.navbar.openOrderHistory();
    await orderHistoryPage.shouldSeePage();
    await orderHistoryPage.shouldSeeOrderCount(1);
    await orderHistoryPage.shouldSeeOrder({ total: orderTotal, bonus, lines: basketLines });
  });
});

