4	/** How long an absence or an unchanged value must hold before the check passes. */
5	export const HOLD_WINDOW_MS = DateHelper.secondsToMs(2);
6	const HOLD_POLL_INTERVAL_MS = 200;
7	
8	export async function expectVisible(locator: Locator, description: string): Promise<void> {
