42	 * The locator must disappear, then stay hidden for the whole hold window.
43	 */
44	export async function expectStaysHidden(locator: Locator, description: string): Promise<void> {
45	  await expectCount(locator, 0, description);
46	  await expectHolds(async () => {
47	    expect(await locator.count(), `${description} does not show`).toBe(0);
48	  });
49	}
