1	import type { BasketLine, DeliveryMethod, OrderTotals } from '@/utils/types/shop';
2	
3	const CENTS_IN_UNIT = 100;
4	const PERCENT = 100;
5	const BONUS_POINT_DIVIDER = 10;
6	const CURRENCY_SIGN = '¤';
7	
8	const toCents = (amount: number): number => Math.round(amount * CENTS_IN_UNIT);
9	const fromCents = (cents: number): number => cents / CENTS_IN_UNIT;
10	
11	/** Expected prices of the shop, calculated in cents to avoid float drift. */
12	export class PriceHelper {
13	  /** `8.99` → `8.99¤`, the way the shop shows prices. */
14	  static format(amount: number): string {
15	    return `${amount.toFixed(2)}${CURRENCY_SIGN}`;
16	  }
17	
18	  /** `5` → `5.00`, the way the shop shows a wallet balance. */
19	  static formatBalance(amount: number): string {
20	    return amount.toFixed(2);
21	  }
22	
23	  static itemsTotal(lines: BasketLine[]): number {
24	    return fromCents(lines.reduce((sum, line) => sum + toCents(line.product.price) * line.quantity, 0));
25	  }
26	
27	  static itemCount(lines: BasketLine[]): number {
28	    return lines.reduce((sum, line) => sum + line.quantity, 0);
29	  }
30	
31	  static orderTotals(lines: BasketLine[], delivery: DeliveryMethod, discountPercent = 0): OrderTotals {
32	    const itemsCents = toCents(PriceHelper.itemsTotal(lines));
33	    const deliveryCents = toCents(delivery.price);
34	    const promotionCents = Math.round((itemsCents * discountPercent) / PERCENT);
35	    return {
36	      items: fromCents(itemsCents),
37	      delivery: fromCents(deliveryCents),
38	      promotion: fromCents(promotionCents),
39	      total: fromCents(itemsCents + deliveryCents - promotionCents),
40	    };
41	  }
42	
43	  /** Bonus points of an order: product price / 10, rounded, × quantity. 1 point = 1.00¤. */
44	  static bonusPoints(lines: BasketLine[]): number {
45	    return lines.reduce((sum, line) => sum + Math.round(line.product.price / BONUS_POINT_DIVIDER) * line.quantity, 0);
46	  }
47	
48	  static add(...amounts: number[]): number {
49	    return fromCents(amounts.reduce((sum, amount) => sum + toCents(amount), 0));
50	  }
51	
52	  static subtract(from: number, amount: number): number {
53	    return fromCents(toCents(from) - toCents(amount));
54	  }
55	}
