1	import { encode } from 'z85';
2	
3	const MONTHS = ['JAN', 'FEB', 'MAR', 'APR', 'MAY', 'JUN', 'JUL', 'AUG', 'SEP', 'OCT', 'NOV', 'DEC'];
4	
5	/**
6	 * Coupon codes as test-cases/README.md defines them: Z85 of `<MMM><YY>-<NN>`.
7	 * The server accepts a coupon only in the month it names, in the local time of the machine.
8	 */
9	export class CouponHelper {
10	  static currentMonthCoupon(discountPercent: number, now = new Date()): string {
11	    return CouponHelper.couponFor(now, discountPercent);
12	  }
13	
14	  static previousMonthCoupon(discountPercent: number, now = new Date()): string {
15	    const previousMonth = new Date(now.getFullYear(), now.getMonth() - 1, 1);
16	    return CouponHelper.couponFor(previousMonth, discountPercent);
17	  }
18	
19	  private static couponFor(date: Date, discountPercent: number): string {
20	    const month = MONTHS[date.getMonth()];
21	    const year = String(date.getFullYear() % 100).padStart(2, '0');
22	    const discount = String(discountPercent).padStart(2, '0');
23	    return encode(`${month}${year}-${discount}`);
24	  }
25	}
