40	/**
41	 * An absence needs a hold, not a retry (docs/core-beliefs.md, 3).
42	 * The locator must disappear, then stay hidden for the whole hold window.
43	 */
44	export async function expectStaysHidden(locator: Locator, description: string): Promise<void> {
45	  await expectCount(locator, 0, description);
46	  await expectHolds(async () => {
47	    expect(await locator.count(), `${description} does not show`).toBe(0);
48	  });
49	}
50	
51	/** The text must stay the same for the whole hold window. */
52	export async function expectKeepsText(locator: Locator, text: string, description: string): Promise<void> {
53	  await expectText(locator, text, description);
54	  await expectHolds(async () => {
55	    expect((await locator.innerText()).trim(), `${description} keeps text ${text}`).toBe(text);
56	  });
57	}
58	
59	async function expectHolds(check: () => Promise<void>): Promise<void> {
60	  const deadline = Date.now() + HOLD_WINDOW_MS;
61	  while (Date.now() < deadline) {
62	    await check();
63	    await new Promise((resolve) => setTimeout(resolve, HOLD_POLL_INTERVAL_MS));
64	  }
65	  await check();
66	}
