18	/** The basket page `/#/basket`. */
19	export class BasketPage extends BasePage {
20	  private readonly title: Locator;
21	  private readonly rows: Locator;
22	  private readonly totalPrice: Locator;
23	  private readonly checkoutButton: Locator;
24	
25	  constructor(page: Page) {
26	    super(page);
27	    const basket = page.locator('app-basket');
28	    this.title = basket.getByRole('heading', { name: /Your Basket/ });
29	    this.rows = basket.locator('mat-row');
30	    this.totalPrice = basket.locator('#price');
31	    this.checkoutButton = basket.getByRole('button', { name: 'Checkout' });
32	  }
33	
34	  private row(product: Product): Locator {
35	    return this.rows.filter({ has: this.page.locator('.mat-column-product', { hasText: product.name }) });
36	  }
37	
38	  private quantity(product: Product): Locator {
39	    return this.row(product).locator('.mat-column-quantity > span');
40	  }
41	
42	  async open(): Promise<void> {
43	    await this.openRoute(UI_ROUTES.basket);
44	    await this.shouldSeePage();
45	  }
46	
47	  async clickIncreaseQuantity(product: Product): Promise<void> {
48	    await this.row(product).locator('.mat-column-quantity').getByRole('button').last().click();
49	  }
50	
51	  async clickDecreaseQuantity(product: Product): Promise<void> {
52	    await this.row(product).locator('.mat-column-quantity').getByRole('button').first().click();
53	  }
54	
55	  async clickRemove(product: Product): Promise<void> {
56	    await this.row(product).locator('.mat-column-remove').getByRole('button').click();
57	  }
58	
59	  async clickCheckout(): Promise<void> {
60	    await this.checkoutButton.click();
61	  }
62	
63	  async shouldSeePage(): Promise<void> {
64	    await expectUrl(this.page, new RegExp(`${UI_ROUTES.basket}$`), 'Basket page');
65	    await expectVisible(this.title, 'Basket title');
66	  }
67	
68	  async shouldSeeRowCount(count: number): Promise<void> {
69	    await expectCount(this.rows, count, 'Basket rows');
70	  }
71	
72	  async shouldSeeLine(line: BasketLine): Promise<void> {
73	    const { product, quantity } = line;
74	    await expectVisible(this.row(product), `Basket row of ${product.name}`);
75	    await expectText(this.quantity(product), String(quantity), `Quantity of ${product.name}`);
76	    await expectText(
77	      this.row(product).locator('.mat-column-price'),
78	      PriceHelper.format(product.price),
79	      `Price of ${product.name}`,
80	    );
81	  }
82	
83	  /** After a rejected change: the quantity must not change later. */
84	  async shouldKeepQuantity(line: BasketLine): Promise<void> {
85	    await expectKeepsText(this.quantity(line.product), String(line.quantity), `Quantity of ${line.product.name}`);
86	  }
87	
88	  async shouldNotSeeProduct(product: Product): Promise<void> {
89	    await expectStaysHidden(this.row(product), `Basket row of ${product.name}`);
90	  }
91	
92	  async shouldSeeTotalPrice(amount: number): Promise<void> {
93	    await expectText(this.totalPrice, `${TOTAL_PRICE_LABEL} ${PriceHelper.format(amount)}`, 'Basket total price');
94	  }
95	
96	  async shouldSeeEmptyBasket(): Promise<void> {
97	    await expectStaysHidden(this.rows, 'Basket rows');
98	  }
99	
100	  async shouldSeeCheckoutDisabled(): Promise<void> {
101	    await expectDisabled(this.checkoutButton, 'Button `Checkout`');
102	  }
103	}
