15	  private readonly orderLines: OrderLinesComponent;
16	  private readonly totalsValues: Locator;
17	
18	  constructor(page: Page) {
19	    super(page);
20	    const root = page.locator('app-order-completion');
21	    this.title = root.getByRole('heading', { level: 1 });
22	    this.orderLines = new OrderLinesComponent(root, true);
23	    // Footer cells: Items, Delivery, Promotion, Total Price, in this order.
24	    this.totalsValues = root.locator('mat-footer-row .mat-column-total-price tr');
25	  }
26	
27	  async shouldSeeOrderPlaced(): Promise<void> {
28	    await expectUrl(this.page, new RegExp(`${UI_ROUTES.orderCompletion}${ORDER_ID_PATTERN}$`), 'Order confirmation page');
29	    await expectText(this.title, UI_MESSAGES.orderPlaced, 'Order confirmation message');
30	  }
31	
32	  /** The order ID from the URL `/#/order-completion/<order ID>`. */
33	  orderId(): string {
34	    const match = this.page.url().match(new RegExp(`order-completion/(${ORDER_ID_PATTERN})$`));
35	    if (!match) {
36	      throw new Error(`No order ID in the URL ${this.page.url()}`);
37	    }
38	    return match[1];
39	  }
