41	  async shouldSeeLines(lines: BasketLine[]): Promise<void> {
42	    await this.orderLines.shouldSeeLines(lines);
43	  }
44	
45	  async shouldSeeTotals(totals: OrderTotals): Promise<void> {
46	    const values = [totals.items, totals.delivery, totals.promotion, totals.total];
47	    const labels = ['Items', 'Delivery', 'Promotion', 'Total Price'];
48	    for (const [index, value] of values.entries()) {
49	      await expectText(this.totalsValues.nth(index), PriceHelper.format(value), labels[index]);
50	    }
51	  }
52	}
